-- The v0.5 retcon (migration 0068, generated by `cargo jackioh patches retcon --from v0.5.0`, issue
-- #2532, SPEC §11 R2532000). Runs after 37_idempotency_keys.sql; profiles 1 and 2 are active by then.
\set ON_ERROR_STOP on

-- As 28 does for 0049: every row the suite seeds carries a name the retcon keeps, so the migration
-- renamed nothing when run.sh applied it; this check seeds rows under the v0.5 line's old names, as
-- production holds them, applies the migration again over them, and rolls back. The names overlap
-- (the old v0.5.7 is the new v0.5.5 while the new v0.5.7 is the old v0.5.11), so each row must be
-- renamed exactly once. This file spells old names on purpose: the retcon's tree rewrite skips it.

\echo '### R2532000: the v0.5 retcon renames each row''s catalog version once ###'
begin;
do $$
declare
  p1 constant uuid := '11111111-1111-1111-1111-111111111111';
  p2 constant uuid := '22222222-2222-2222-2222-222222222222';
  rec_of constant text := '{"pilots": {"p1": "ai", "p2": "ai"}, "game": {"turns": 9}, "versions": 2}';
begin
  insert into public.cards (id, card_index, name, set_id, type, tags, rarity, token, cost, catalog_version)
  values ('r2532-a', '2532.1', 'Card under v0.5.11', 'Core', 'Unit', '{}', 'Common', false, '1'::jsonb, 'v0.5.11'),
         ('r2532-b', '2532.2', 'Card under v0.5.7', 'Core', 'Unit', '{}', 'Common', false, '1'::jsonb, 'v0.5.7'),
         ('r2532-c', '2532.3', 'Card under v0.4.12d', 'Core', 'Unit', '{}', 'Common', false, '1'::jsonb, 'v0.4.12d');
  update app.settings set value = '"v0.5.11"' where key = 'catalog_version';
  perform set_config('r2532.grants', (select count(*)::text from public.collection_grants), true);

  insert into public.decks (id, profile_id, name, cards, catalog_version)
  values ('d2532000-0000-4000-8000-000000000001', p1, 'Under v0.5.11', '["core-001"]', 'v0.5.11');
  insert into public.matches (id, status, seed, p1_profile_id, p2_profile_id, p1_deck, p2_deck,
                              catalog_version, ceiling_at, started_at, ended_at)
  values ('e2532000-0000-4000-8000-000000000007', 'over', 'r2532-7', p1, p2, '[]', '[]', 'v0.5.7', now(), now(), now()),
         ('e2532000-0000-4000-8000-000000000011', 'over', 'r2532-11', p1, p2, '[]', '[]', 'v0.5.11', now(), now(), now());

  -- Two development ids whose new names would meet the other's old one, and a live record.
  insert into public.game_records (id, source, mode, patch, record, folded)
  select g.id, g.source, 'random', g.patch,
         rec_of::jsonb || jsonb_build_object('id', g.id, 'source', g.source, 'mode', 'random', 'patch', g.patch),
         false
    from (values ('e2532000-0000-4000-8000-0000000000aa', 'live', 'v0.5.11'),
                 ('dev:v0.5.7:r2532:1', 'dev', 'v0.5.7'),
                 ('dev:v0.5.11:r2532:1', 'dev', 'v0.5.11'),
                 ('dev:v0.5.11:learned-v0.5.10-20261030-1:2', 'dev', 'v0.5.11'),
                 ('dev:v0.4.12d:r2532:1', 'dev', 'v0.4.12d')) as g (id, source, patch);
  -- A record of a kept version is left as it is, its marker the first retcon's.
  update public.game_records set record = record || '{"versions": 2}'::jsonb where id = 'dev:v0.4.12d:r2532:1';

  -- The totals key on the patch: the old v0.5.7's row and the old v0.5.11's must not meet.
  insert into public.record_totals (patch, source, mode, p1_pilot, p2_pilot, records)
  values ('v0.5.7', 'dev', 'random', 'ai', 'ai', 7), ('v0.5.11', 'dev', 'random', 'ai', 'ai', 11);
  insert into public.game_totals (patch, source, mode, p1_pilot, p2_pilot, total)
  values ('v0.5.7', 'dev', 'random', 'ai', 'ai', '{"games": 7}'),
         ('v0.5.11', 'dev', 'random', 'ai', 'ai', '{"games": 11}');
  -- A card's co-played map keeps the record where two cards first met: renamed as the record is,
  -- v0.5.1 never read inside v0.5.10.
  insert into public.card_totals (patch, source, mode, pilot, card, stats, co)
  values ('v0.5.11', 'dev', 'random', 'ai', 'core-001', '{"n": 11}',
          '{"core-002": [1, 1, "dev:v0.5.11:learned-v0.5.10-20261030-1:2", 0, 0], "core-003": [1, 0, "e2532000-0000-4000-8000-0000000000aa", 1, 2]}'),
         ('v0.5.7', 'dev', 'random', 'ai', 'core-001', '{"n": 7}', '{"core-002": [1, 1, "dev:v0.5.7:r2532:1", 0, 0]}'),
         ('v0.4.12d', 'dev', 'random', 'ai', 'core-001', '{"n": 4}', '{"core-002": [1, 1, "dev:v0.4.12d:r2532:1", 0, 0]}');
  insert into public.decklist_totals (patch, list, deck, games, wins, first_record, first_seat)
  values ('v0.5.11', 'l2532', '[]', 11, 6, 'dev:v0.5.11:r2532:1', 0),
         ('v0.5.7', 'l2532', '[]', 7, 3, 'dev:v0.5.7:r2532:1', 1);
end $$;

\i /tmp/0068_v0_5_retcon.sql

do $$
declare
  v text;
  n int;
begin
  if app.catalog_version() <> 'v0.5.7' then
    raise exception 'FAIL (R2532000): the live version is %, expected v0.5.7', app.catalog_version();
  end if;
  if (select count(*)::text from public.collection_grants) <> current_setting('r2532.grants') then
    raise exception 'FAIL (R2532000): the rename granted cards';
  end if;
  select string_agg(id || '=' || catalog_version, ',' order by id) into v from public.cards where id like 'r2532-%';
  if v <> 'r2532-a=v0.5.7,r2532-b=v0.5.5,r2532-c=v0.4.12d' then
    raise exception 'FAIL (R2532000): the cards are %', v;
  end if;
  if (select catalog_version from public.decks where id = 'd2532000-0000-4000-8000-000000000001') <> 'v0.5.7' then
    raise exception 'FAIL (R2532000): the deck saved under v0.5.11 was not renamed once';
  end if;
  select string_agg(catalog_version, ',' order by seed) into v from public.matches where seed like 'r2532-%';
  if v <> 'v0.5.7,v0.5.5' then
    raise exception 'FAIL (R2532000): the matches are % (r2532-11, r2532-7)', v;
  end if;

  select string_agg(id || '=' || patch, ',' order by id) into v from public.game_records
   where (id like 'dev:%r2532%' or id = 'e2532000-0000-4000-8000-0000000000aa') and patch <> 'v0.4.12d';
  if v <> 'dev:v0.5.5:r2532:1=v0.5.5,dev:v0.5.7:r2532:1=v0.5.7,e2532000-0000-4000-8000-0000000000aa=v0.5.7' then
    raise exception 'FAIL (R2532000): the game records are %', v;
  end if;
  if not exists (select 1 from public.game_records where id = 'dev:v0.5.7:learned-v0.5.6c-20261030-1:2' and patch = 'v0.5.7') then
    raise exception 'FAIL (R2532000): a learned series'' version was not renamed with the record''s';
  end if;
  if (select record -> 'versions' from public.game_records where id = 'dev:v0.4.12d:r2532:1') <> '2'::jsonb then
    raise exception 'FAIL (R2532000): a record of a kept version was rewritten';
  end if;
  select count(*) into n from public.game_records
   where (id like 'dev:%r2532%' or id like 'dev:%learned%' or id = 'e2532000-0000-4000-8000-0000000000aa')
     and patch <> 'v0.4.12d'
     and (record ->> 'id' <> id or record ->> 'patch' <> patch or record -> 'versions' <> '3'::jsonb
          or record #>> '{game,turns}' <> '9');
  if n <> 0 then
    raise exception 'FAIL (R2532000): % records'' copies do not match their row, or lost their detail', n;
  end if;
  if exists (select 1 from public.game_records where id like 'dev:~%') then
    raise exception 'FAIL (R2532000): a record kept its passing name';
  end if;

  select string_agg(patch || '=' || records, ',' order by patch) into v from public.record_totals
   where patch in ('v0.5.5', 'v0.5.7', 'v0.5.11');
  if v <> 'v0.5.5=7,v0.5.7=11' then
    raise exception 'FAIL (R2532000): the record totals are %', v;
  end if;
  select string_agg(patch || '=' || (total ->> 'games'), ',' order by patch) into v from public.game_totals
   where patch in ('v0.5.5', 'v0.5.7', 'v0.5.11');
  if v <> 'v0.5.5=7,v0.5.7=11' then
    raise exception 'FAIL (R2532000): the game totals are %', v;
  end if;
  if exists (select 1 from public.game_totals where starts_with(patch, '~')) then
    raise exception 'FAIL (R2532000): a game total kept its passing name';
  end if;
  select string_agg(patch || '=' || (stats ->> 'n') || ':' || (co #>> '{core-002,2}'), ',' order by patch) into v
    from public.card_totals where card = 'core-001' and patch in ('v0.4.12d', 'v0.5.5', 'v0.5.7', 'v0.5.11');
  if v <> 'v0.4.12d=4:dev:v0.4.12d:r2532:1,v0.5.5=7:dev:v0.5.5:r2532:1,v0.5.7=11:dev:v0.5.7:learned-v0.5.6c-20261030-1:2' then
    raise exception 'FAIL (R2532000): the card totals are %', v;
  end if;
  if (select co #>> '{core-003,2}' from public.card_totals where card = 'core-001' and patch = 'v0.5.7') <> 'e2532000-0000-4000-8000-0000000000aa' then
    raise exception 'FAIL (R2532000): a live record id in a co-played map changed';
  end if;
  select string_agg(patch || '=' || games || ':' || first_record, ',' order by patch) into v
    from public.decklist_totals where list = 'l2532';
  if v <> 'v0.5.5=7:dev:v0.5.5:r2532:1,v0.5.7=11:dev:v0.5.7:r2532:1' then
    raise exception 'FAIL (R2532000): the decklist totals are %', v;
  end if;
  raise notice 'OK (R2532000): every row renamed once, the copies kept and marked 3, the co-played and decklist record ids renamed with their records, a kept version left alone';
end $$;
rollback;
